'use strict';
const vividHome=homeHTML;
homeHTML=function(){const box=document.createElement('div');box.innerHTML=vividHome();const landing=box.querySelector('.landing'),intro=box.querySelector('.landing-intro'),cards=box.querySelector('.showcase');if(landing&&intro&&cards){const hero=document.createElement('section');hero.className='vivid-hero';hero.setAttribute('aria-label','برامج ولاء رجعة');landing.prepend(hero);hero.append(intro,cards);intro.querySelector('h1').innerHTML='عميل اليوم.<br><span>عميل كل يوم.</span>';intro.querySelector('.landing-kicker').textContent='ولاء يليق بنشاطك';cards.insertAdjacentHTML('beforeend','<div class="hero-orbit" aria-hidden="true">↶</div><span class="hero-tag" aria-hidden="true">كل رجعة، مكافأة ✦</span>');}return box.innerHTML;};
const beforeBrandRender=render;
render=function(){beforeBrandRender();document.querySelectorAll('.brand').forEach(el=>{el.innerHTML='<img class="rijaa-brand-logo" src="/brand-logo.png" alt="رجعة — نظام الولاء" width="240" height="96">';});};
render();
const carouselHome=homeHTML;
homeHTML=function(){const box=document.createElement('div');box.innerHTML=carouselHome();const stage=box.querySelector('.showcase');if(stage){stage.classList.add('showcase-3d');stage.setAttribute('aria-label','عرض بطاقات الولاء ثلاثي الأبعاد');const ring=document.createElement('div');ring.className='card-ring';stage.querySelectorAll('.showcase-item').forEach((el,i)=>{el.style.setProperty('--slot',i);ring.append(el);});stage.prepend(ring);stage.querySelector('.hero-orbit')?.remove();stage.insertAdjacentHTML('beforeend','<div class="carousel-controls"><button type="button" class="rotate-card" data-rotate="-1" aria-label="البطاقة السابقة">→</button><span class="carousel-caption" aria-live="polite">بطاقة الزيارات</span><button type="button" class="rotate-card" data-rotate="1" aria-label="البطاقة التالية">←</button></div><p class="carousel-hint">اسحب البطاقات واكتشف برنامجك</p>');}return box.innerHTML;};
function bindCardShowcase(){const stage=document.querySelector('.showcase-3d');if(!stage)return;let index=0,startX=null;const names=['بطاقة الزيارات','بطاقة الخصومات','بطاقة النقاط'];const rotate=step=>{index+=step;stage.style.setProperty('--rotation',`${-index*120}deg`);const active=((index%3)+3)%3;stage.querySelector('.carousel-caption').textContent=names[active];stage.querySelectorAll('.showcase-item').forEach((el,i)=>{let rel=((i-active+3)%3);if(rel===2)rel=-1;el.style.setProperty('--x',rel*150+'px');el.style.setProperty('--z',rel===0?'100px':'-90px');el.style.setProperty('--tilt',rel*-38+'deg');el.setAttribute('aria-hidden',i===active?'false':'true');});};stage.querySelectorAll('[data-rotate]').forEach(b=>b.addEventListener('click',()=>rotate(Number(b.dataset.rotate))));stage.addEventListener('pointerdown',e=>{if(e.target.closest('button')||!e.isPrimary)return;startX=e.clientX;stage.setPointerCapture(e.pointerId);});stage.addEventListener('pointerup',e=>{if(startX!==null&&Math.abs(e.clientX-startX)>35)rotate(e.clientX>startX?-1:1);startX=null;});stage.addEventListener('pointercancel',()=>startX=null);rotate(0);}
const carouselRender=render;
render=function(){carouselRender();bindCardShowcase();};
render();

